const html = $input.first().json.data || '';

const matches = [...html.matchAll(/href=["'](https:\/\/ieltsmaterial\.com\/[^"']*practice-test[^"']*)["']/gi)].map(m => m[1]);

const uniqueUrls = [...new Set(matches)].filter(url => 
  url !== 'https://ieltsmaterial.com/ielts-writing-practice-test/' && 
  !url.includes('/ielts-practice-tests/')
);

return uniqueUrls.map(url => ({
  json: { url }
}));

const html = $input.item.json.data || '';

const articleMatch = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
const rawArticle = articleMatch ? articleMatch[1] : html;

const cleanText = rawArticle
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;|&rsquo;|&lsquo;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

let sourceUrl = '';
try {
  sourceUrl = $('lọc link').item.json.url || '';
} catch (e) {
  sourceUrl = $input.item.json.url || '';
}

return {
  json: {
    clean_article_text: cleanText,
    source_url: sourceUrl
  }
};

